class Solution {
  public int[] assignElements(int[] groups, int[] elements) {
    int max = 0;
    for (int g : groups) max = Math.max(max, g);
    int[] first = new int[max + 1];
    java.util.Arrays.fill(first, -1);
    boolean[] seen = new boolean[max + 1];
    for (int j = 0; j < elements.length; j++) {
      int e = elements[j];
      if (e > max || seen[e]) continue;
      seen[e] = true;
      for (int m = e; m <= max; m += e) if (first[m] < 0) first[m] = j;
    }
    int[] ans = new int[groups.length];
    for (int i = 0; i < groups.length; i++) ans[i] = first[groups[i]];
    return ans;
  }
}
